@Component("loanPayment-subscriber")
public class LoanPaymentSubscriber extends BaseSubscriber {

	public LoanPaymentSubscriber() {
	}
	
    public SubscriptionQueryResult<List<LoanPayment>, LoanPayment> loanPaymentSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllLoanPaymentQuery(), 
                		ResponseTypes.multipleInstancesOf(LoanPayment.class),
                		ResponseTypes.instanceOf(LoanPayment.class));
    }

    public SubscriptionQueryResult<LoanPayment, LoanPayment> loanPaymentSubscribe(@DestinationVariable UUID loanPaymentId) {
        return queryGateway
                .subscriptionQuery(new FindLoanPaymentQuery(new LoadLoanPaymentFilter(loanPaymentId)), 
                		ResponseTypes.instanceOf(LoanPayment.class),
                		ResponseTypes.instanceOf(LoanPayment.class));
    }





}

